	export default {
    async asyncData({ redirect, $axios }) {

			return {
        $axios,
        redirect,
			}
		},
    data() {
      return {
        testimonial: [],
        lang: 'en',
      }
    },
    created() {
      const self = this;
      const queryId = this.$route.query.id;

      if(!queryId) {
        this.redirect('/404');
        return;
      }

      this.$axios.$get(`/testimonial/en/${queryId}`).then((response) => {
        this.testimonial = response;
      }).catch(error => {
        self.redirect('/404');
      });
    }
	}
